private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (i >= bb.limit()) {
        throw new ArrayIndexOutOfBoundsException("Buffer is out of bounds");
    }
    byte b = bb.get(i++);
    int value = b & 0xFF;
    if ((value & 0x80) == 0) {
        // Single-byte character
        sb.append((char) value);
    } else {
        // Multi-byte character
        if ((value & 0xE0) == 0xE0) {
            // Three-byte character (header 0xE0)
            value = (value & 0xF) | bb.get(i++) << 6 | bb.get(i++) << 12;
        } else if ((value & 0xC0) == 0xC0) {
            // Two-byte character (header 0xC0)
            value = (value & 3) | bb.get(i++) << 6;
        }
        sb.append((char) value);
    }
    return i;
}
