import java.util.List;
import java.util.LinkedList;

public class TimeRangeBuilder {
    private static final long FETCH_DATA_DURATION = 1000; // milliseconds

    protected List<TimeRange> buildTimeRanges(long start, long end) {
        list<TimeRange> ranges = new LinkedList<>();

        if (start + FETCH_DATA_DURATION > end) {
            ranges.add(new TimeRange(start, end));
        } else if (start - FETCH_DATA_DURATION < end) {
            ranges.add(new TimeRange(start - FETCH_DATA_DURATION, start)); // split at start time
            ranges.add(new TimeRange(end, end + FETCH_DATA_DURATION)); // split at end time
        } else {
            ranges.add(new TimeRange(start, end)); // no need to split
        }

        return ranges;
    }
}
