public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength) throws IllegalArgumentException{
    if (byteArrayValue == null) {
        if (byteLength == 0) {
            return this;
        } else {
            throw new IllegalArgumentException("byteArrayValue is null and byteLength is non-zero.");
        }
    } else if (byteArrayValue.length - byteOffset < byteLength) {
        throw new IllegalArgumentException("byteArrayValue is null and byteOffset + byteLength exceeds the length of byteArrayValue.");
    }

    int loc0 = this.length;
    int loc2 = byteOffset;

    while (loc2 < byteOffset + byteLength) {
        this.data[loc0] = byteArrayValue[loc2];
        loc0++;
        loc2++;
    }

    this.length = loc0;
    return this;
}
