public static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null && suffix == null) {
        return true;
    }

    int len = (str == null) ? 0 : str.length();
    int suffixLen = (suffix == null) ? 0 : suffix.length();

    if (len < suffixLen) {
        return false;
    }

    int end = len - suffixLen;
    if (ignoreCase) {
        end = end - (end % 2); // Ignore case by trimming the extra characters
    }

    return str.regionMatches(ignoreCase ? 0 : 0, end, suffix, 0, suffixLen);
}
