public static List<PathSegmentImpl> decodePath(final URI u, final boolean decode){
    if (u == null) {
        return null;
    }
    List<PathSegmentImpl> pathSegments = new ArrayList<>();

    String uriPath = u.getRawPath();

    if (decode) {
        uriPath = URLDecoder.decode(uriPath, StandardCharsets.UTF_8);
    }

    String lastSegment = null;
    StringBuilder currentSegment = new StringBuilder();

    for (int i = 0; i < uriPath.length(); i++) {
        char ch = uriPath.charAt(i);

        if (ch == '/') {
            if (lastSegment != null) {
                pathSegments.add(new PathSegmentImpl(currentSegment.toString()));
                currentSegment = new StringBuilder();
            }
            lastSegment = null;
            continue;
        }

        currentSegment.append(ch);

        if (i == uriPath.length() - 1) {
            pathSegments.add(new PathSegmentImpl(currentSegment.toString()));
        }
    }

    return pathSegments;
}
