import org.javatuples.Pair;

public class BoxUtils {
    /**
     * Split a box along the x axis into two equal boxes.
     * @param box the box to split
     * @return a pair with the two resulting boxes
     */
    public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
        int width = (int) box.getWidth();
        int halfWidth = width / 2;
        Rectangle2D upperHalf = new Rectangle2D.Double(box.getMinX(), box.getMinY(), halfWidth, box.getHeight());
        Rectangle2D lowerHalf = new Rectangle2D.Double(box.getMinX() + halfWidth, box.getMinY(), halfWidth, box.getHeight());
        return Pair.with(upperHalf, lowerHalf);
    }
}
