private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Temporary variables to help manage the traversal near the boundary
    Node left = start;
    Node right = stop;
    Node middle = null;

    while (true) {
        // Calculate the new middle node based on the direction
        if (dir == 0) {
            middle = left;
            left = left.getNext(dir); // Move left
        } else if (dir == 1) {
            middle = right;
            right = right.getNext(dir); // Move right
        } else {
            throw new IllegalArgumentException("Invalid direction");
        }

        // If a node is satisfied, stop and return an outer face circulator
        if (predicate.test(middle)) {
            return new OuterFaceCirculator(start, dir);
        }

        // If we reach the boundary nodes, return a circulator to the boundary
        if (middle == null || middle == start || middle == stop) {
            return new OuterFaceCirculator(middle, dir);
        }
    }
}
