private static String unescapeId(String input) {
    if (input == null) {
        throw new IllegalArgumentException("Input cannot be null");
    }

    boolean started = false;
    StringBuilder sb = new StringBuilder();
    for (char c : input.toCharArray()) {
        if (c == '\\') {
            if (started) {
                if (c == 'n' && sb.length() != 0) {
                    sb.append('\n');
                } else if (c == 't' && sb.length() != 0) {
                    sb.append('\t');
                } else {
                    sb.append(c);
                }
            }
            started = true;
        } else if (c == '"') {
            if (!started) {
                started = true;
            } else {
                sb.append('"');
            }
        } else {
            sb.append(c);
            started = false;
        }
    }
    return sb.toString();
}
