    int secondByte = intValue >>> 16;
    int thirdByte = intValue >>> 8;
    int fourthByte = intValue;

    // Get the data array of the ByteVector
    byte[] data = this.data;

    // Check if there is enough space to write the four bytes
    int length = this.length;
    if (length + 4 > data.length) {
        // Enlarge the ByteVector by a factor of 2
        enlarge(4);
    }

    // Set the first four bytes in the data array
    data[length++] = (byte) firstByte;
    data[length++] = (byte) secondByte;
    data[length++] = (byte) thirdByte;
    data[length++] = (byte) fourthByte;

    // Update the length of the ByteVector
