private int readUntilTagBoundaries(int currentTag) throws IOException {
    byte nextByte = readByte();
    while (nextByte != -1 && !isTagBoundaries(nextByte)) {
        currentTag = (currentTag << 8) | (nextByte & 0xFF);
        nextByte = readByte();
    }
    return currentTag;
}

private boolean isTagBoundaries(byte currentByte) {
    return ((currentByte & 0xFFFFFF80) == 0x00);
}
